const profiles = $('Fetch Funding Profiles').all().map(i => i.json);
const fees = $('Fetch Insurer Fee Schedule').all().map(i => i.json);
const invoices = $('Split Out Invoices').all().map(i => i.json);

// Claims already in the ledger: pending_review and failed_validation re-validate on each run; anything submitted or final never re-processes
const existingClaims = {};
for (const r of $('Fetch Existing WC Claims').all()) { if (r.json && r.json.claim_reference) existingClaims[String(r.json.claim_reference).trim()] = String(r.json.status || ''); }

const feeMap = {};
for (const f of fees) { feeMap[String(f.item_code).trim().toUpperCase()] = f; }
const profByPatient = {};
for (const p of profiles) {
  if (String(p.active).toLowerCase() === 'yes') profByPatient[String(p.patient_id).trim()] = p;
}

const batchId = 'WC-' + $today.toFormat('yyyyLLdd');
const seen = {};
const tallyUsed = {};
const out = [];
const inputs = $input.all();

for (let idx = 0; idx < inputs.length; idx++) {
  const resp = inputs[idx].json;
  const inv = invoices[idx] || resp;

  let patientId = String(inv.patient_id ?? inv.patientId ?? '').trim();
  if (!patientId && inv.patient && inv.patient.id) patientId = String(inv.patient.id);
  if (!patientId && inv.patient && inv.patient.links && inv.patient.links.self) {
    const m = String(inv.patient.links.self).match(/patients[/]([0-9]+)/);
    if (m) patientId = m[1];
  }

  const invoiceNumber = String(inv.invoice_number ?? inv.number ?? '').trim();
  const serviceDate = String(inv.service_date ?? inv.issue_date ?? '').slice(0, 10);

  let lines = Array.isArray(resp.invoice_items) ? resp.invoice_items : (Array.isArray(inv.items) ? inv.items : []);
  if (!lines.length) lines = [inv];

  for (const line of lines) {
    let code = String(line.item_code ?? line.code ?? '').trim().toUpperCase();
    if (!code || !feeMap[code]) {
      const m2 = String((line.name ?? '') + ' ' + (line.description ?? '')).toUpperCase().match(/[A-Z]{2,4}[0-9]{3}/);
      if (m2 && feeMap[m2[0]]) code = m2[0];
    }

    // Only lines coded with an insurer fee-schedule item belong to this workflow
    if (!code || !feeMap[code]) continue;

    const fee = feeMap[code];
    const quantity = Number(line.quantity ?? 1) || 1;
    const unitPrice = Number(line.unit_price ?? line.price ?? 0);
    const errors = [];

    const profile = profByPatient[patientId];
    if (!profile) errors.push('No active workers comp / CTP funding profile for patient id "' + patientId + '"');

    if (profile && !String(profile.claim_number ?? '').trim()) errors.push('Funding profile has no insurer claim number');
    if (profile && !String(profile.approval_reference ?? '').trim()) errors.push('No treatment approval (AHTR) reference on file');

    if (profile && serviceDate) {
      const exp = String(profile.approval_expiry ?? '').slice(0, 10);
      if (exp && serviceDate > exp) errors.push('Service date ' + serviceDate + ' is after approval expiry ' + exp + ' (submit a new AHTR)');
    }

    const approved = profile ? (Number(profile.sessions_approved) || 0) : 0;
    const usedBase = profile ? (Number(profile.sessions_used) || 0) : 0;
    const usedTally = tallyUsed[patientId] || 0;
    const remainingBefore = approved - usedBase - usedTally;
    if (profile && remainingBefore < quantity) errors.push('Only ' + Math.max(0, remainingBefore) + ' approved sessions remaining under ' + (profile.approval_reference || 'the current approval') + ' (submit a new AHTR before treating)');

    if (unitPrice > Number(fee.rate)) errors.push('Unit price $' + unitPrice.toFixed(2) + ' exceeds the gazetted rate $' + Number(fee.rate).toFixed(2) + ' for ' + code);
    if (!(quantity > 0)) errors.push('Quantity must be greater than zero');
    if (!serviceDate) errors.push('Missing service date');

    const claimRef = (invoiceNumber || 'NOINV') + '-' + code + '-' + serviceDate;

    // Status protection: skip claims already submitted, rejected or paid so they are never re-staged or re-sent
    const prior = existingClaims[claimRef];
    if (prior && prior !== 'failed_validation' && prior !== 'pending_review') continue;

    if (seen[claimRef]) errors.push('Duplicate claim line in this batch: ' + claimRef);
    seen[claimRef] = true;

    const valid = errors.length === 0;
    if (valid) tallyUsed[patientId] = usedTally + quantity;

    const usedNew = usedBase + (tallyUsed[patientId] || usedTally);
    const remainingAfter = approved - usedNew;

    out.push({ json: {
      claim_reference: claimRef,
      invoice_number: invoiceNumber,
      patient_id: patientId,
      participant_name: profile ? (profile.patient_name || '') : '',
      support_item_number: code,
      support_item_name: fee.item_name || '',
      service_date: serviceDate,
      quantity: quantity,
      unit_price: unitPrice,
      total: Math.round(quantity * unitPrice * 100) / 100,
      funder: profile ? profile.funder : 'workers_comp',
      insurer_name: profile ? (profile.insurer_name || '') : '',
      insurer_email: profile ? (profile.insurer_email || '') : '',
      claim_number: profile ? (profile.claim_number || '') : '',
      approval_reference: profile ? (profile.approval_reference || '') : '',
      sessions_used_new: valid ? usedNew : usedBase,
      remaining_after: valid ? remainingAfter : (approved - usedBase),
      status: valid ? 'pending_review' : 'failed_validation',
      validation_errors: errors.join('; '),
      batch_id: batchId
    }});
  }
}
return out;

const failed = $('Validate WC Claims').all().map(i => i.json).filter(c => c.status === 'failed_validation');
let rows = '';
for (const c of failed) {
  rows += '<tr><td>' + c.claim_reference + '</td><td>' + (c.participant_name || 'Unknown') + '</td><td>' + (c.claim_number || '-') + '</td><td>' + c.validation_errors + '</td></tr>';
}
const html = '<h2>Workers comp / CTP claims failing validation (' + failed.length + ')</h2>' +
  '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">' +
  '<tr><th>Claim</th><th>Patient</th><th>Insurer claim no.</th><th>Problems</th></tr>' + rows + '</table>' +
  '<p>Fix the funding profile (claim number, AHTR approval, sessions) in the funding_profiles data table, or correct the invoice in the PMS, then re-run. Nothing invalid was invoiced to an insurer.</p>';
return [{ json: { html: html, count: failed.length } }];

const pend = $('Validate WC Claims').all().map(i => i.json).filter(c => c.status === 'pending_review');
if (!pend.length) return [];
let total = 0;
for (const c of pend) total += Number(c.total) || 0;
const html = '<h2>' + pend.length + ' workers comp / CTP claim(s) are ready for final review</h2>' +
  '<p>Total value: $' + total.toFixed(2) + '. Nothing has been sent to any insurer yet.</p>' +
  '<p>Review each claim and approve or reject it on the dashboard:</p>' +
  '<p><a href="https://YOUR_N8N_INSTANCE/webhook/claims-review">Open the claims review dashboard</a></p>' +
  '<p style="color:#888;font-size:12px">The link works once the 2.3) Claims Review workflow is published.</p>';
return [{ json: { html: html, count: pend.length, total: total } }];
